import 'package:flutter/material.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
class MediaGalleryScreen extends StatelessWidget{const MediaGalleryScreen({super.key});@override Widget build(BuildContext c){final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null)return const Scaffold(body:Center(child:Text('Please sign in.')));return Scaffold(appBar:AppBar(title:const Text('Your Media gallery')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('posts').where('userId',isEqualTo:uid).snapshots(),builder:(c,s){if(s.hasError)return Center(child:Text('Unable to load media.'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=s.data!.docs.where((d)=>(d.data()['mediaUrl']??'').toString().isNotEmpty).toList();if(docs.isEmpty)return const Center(child:Text('No media yet.'));return GridView.builder(padding:const EdgeInsets.all(8),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,crossAxisSpacing:6,mainAxisSpacing:6),itemCount:docs.length,itemBuilder:(c,i){final d=docs[i].data();final url=(d['mediaUrl']??'').toString();return ClipRRect(borderRadius:BorderRadius.circular(10),child:Image.network(url,fit:BoxFit.cover,errorBuilder:(_,e,s)=>const Icon(Icons.broken_image_outlined)));});}));}}